    rdfs:label "Diagnostic purpose"@en ;
    rdfs:subClassOf ea:Purpose , ea:FormativePurpose ;
    rdfs:comment "Tension noted: Passage 2 lists placement, formative, summative, and diagnostic as coordinate categories, whereas subsequent passages state that diagnostic assessment is a common form of formative assessment ('A common form of formative assessment is diagnostic assessment'). Both claims are captured."@en .

ea:InterimPurpose a owl:Class ;
    rdfs:label "Interim purpose"@en ;
    skos:altLabel "Benchmark purpose"@en ;
    rdfs:subClassOf ea:Purpose .

ea:ScreeningPurpose a owl:Class ;
    rdfs:label "Screening purpose"@en ;
    rdfs:subClassOf ea:Purpose .

ea:FormativePurpose owl:disjointWith ea:SummativePurpose .
ea:PlacementPurpose owl:disjointWith ea:SummativePurpose .

ea:PlacementAssessment a owl:Class ;
    rdfs:label "Placement assessment"@en ;
    skos:altLabel "Initial assessment"@en , "Placement evaluation"@en , "Pre-assessment"@en , "Threshold knowledge test"@en , "TKT"@en ;
